import 'package:flutter/foundation.dart';

// Global app language (default: 'en')
String _appLanguage = 'en';
final ValueNotifier<String> appLanguageNotifier = ValueNotifier('en');
const supportedAppLanguages = {'en', 'ar', 'fr'};

String getAppLanguage() => _appLanguage;
void setAppLanguage(String lang) {
  final normalized = supportedAppLanguages.contains(lang) ? lang : 'en';
  if (_appLanguage == normalized) return;
  _appLanguage = normalized;
  appLanguageNotifier.value = normalized;
}

