  static Map<String, String> _activeMap() {
    switch (getAppLanguage()) {
      case 'ar':
        return _ar;
      case 'fr':
        return _fr;
      default:
        return _en;
    }
  }

  static String get(String key) {
    return _activeMap()[key] ?? _en[key] ?? key;
  }

  static String format(String key, Map<String, Object> values) {
    var text = get(key);
    for (final entry in values.entries) {
      text = text.replaceAll('{${entry.key}}', entry.value.toString());
    }
    return text;
  }

  static const _monthsEn = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];
  static const _monthsAr = [
    'يناير',
    'فبراير',
    'مارس',
    'أبريل',
    'مايو',
    'يونيو',
    'يوليو',
    'أغسطس',
    'سبتمبر',
    'أكتوبر',
    'نوفمبر',
    'ديسمبر',
  ];
  static const _monthsFr = [
    'Janv.',
    'Févr.',
    'Mars',
    'Avr.',
    'Mai',
    'Juin',
    'Juil.',
    'Août',
    'Sept.',
    'Oct.',
    'Nov.',
    'Déc.',
  ];

  static List<String> get _months {
    switch (getAppLanguage()) {
      case 'ar':
        return _monthsAr;
      case 'fr':
        return _monthsFr;
      default:
        return _monthsEn;
    }
  }

  static String monthName(int month) => _months[(month - 1).clamp(0, 11)];

  static String formatDate(DateTime dt, {bool withYear = false}) {
    final m = _months[dt.month - 1];
    switch (getAppLanguage()) {
      case 'ar':
      case 'fr':
        return withYear ? '${dt.day} $m ${dt.year}' : '${dt.day} $m';
      default:
        return withYear ? '$m ${dt.day}, ${dt.year}' : '$m ${dt.day}';
    }
  }

  static const _daysEn = [
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday',
    'Sunday',
  ];
  static const _daysAr = [
    'الإثنين',
    'الثلاثاء',
    'الأربعاء',
    'الخميس',
    'الجمعة',
    'السبت',
    'الأحد',
  ];
  static const _daysFr = [
    'Lundi',
    'Mardi',
    'Mercredi',
    'Jeudi',
    'Vendredi',
    'Samedi',
    'Dimanche',
  ];

  static List<String> get _days {
    switch (getAppLanguage()) {
      case 'ar':
        return _daysAr;
      case 'fr':
        return _daysFr;
      default:
        return _daysEn;
    }
  }

  static String dayName(DateTime dt) => _days[dt.weekday - 1];

  static String weekdayName(int weekday) => _days[(weekday - 1).clamp(0, 6)];

  static const _daysShortEn = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  // Arabic weekday names all share the "ال" prefix, so a 1-2 letter slice of
  // the full name is ambiguous — use distinct short forms instead.
  static const _daysShortAr = ['اثنين', 'ثلاثاء', 'أربعاء', 'خميس', 'جمعة', 'سبت', 'أحد'];
  static const _daysShortFr = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];

  /// Short, distinct weekday label (1=Monday..7=Sunday) for tight spaces
  /// like a calendar header row — never just a sliced-off first letter.
  static String weekdayShort(int weekday) {
    final i = (weekday - 1).clamp(0, 6);
    switch (getAppLanguage()) {
      case 'ar':
        return _daysShortAr[i];
      case 'fr':
        return _daysShortFr[i];
      default:
        return _daysShortEn[i];
    }
  }

  static String formatFullDate(DateTime dt) {
    final day = dayName(dt);
    final m = _months[dt.month - 1];
    return getAppLanguage() == 'ar'
        ? '$day، ${dt.day} $m ${dt.year}'
        : getAppLanguage() == 'fr'
        ? '$day ${dt.day} $m ${dt.year}'
        : '$day, $m ${dt.day}, ${dt.year}';
  }

  // Player position is stored as a fixed English string (add_edit_player_page's
  // _positions chips) — translate it for display without touching the stored
  // value. Unknown/custom strings pass through unchanged.
