    'Goalkeeper': 'حارس مرمى',
    'Centre-Back': 'قلب دفاع',
    'Right-Back': 'ظهير أيمن',
    'Left-Back': 'ظهير أيسر',
    'Defensive Mid': 'وسط دفاعي',
    'Central Mid': 'وسط ميدان',
    'Attacking Mid': 'وسط هجومي',
    'Right Wing': 'جناح أيمن',
    'Left Wing': 'جناح أيسر',
    'Striker': 'مهاجم',
  };
  static const _positionsFr = {
    'Goalkeeper': 'Gardien',
    'Centre-Back': 'Défenseur central',
    'Right-Back': 'Arrière droit',
    'Left-Back': 'Arrière gauche',
    'Defensive Mid': 'Milieu défensif',
    'Central Mid': 'Milieu central',
    'Attacking Mid': 'Milieu offensif',
    'Right Wing': 'Ailier droit',
    'Left Wing': 'Ailier gauche',
    'Striker': 'Attaquant',
  };

  static String positionLabel(String raw) {
    if (raw.isEmpty) return raw;
    switch (getAppLanguage()) {
      case 'ar':
        return _positionsAr[raw] ?? raw;
      case 'fr':
        return _positionsFr[raw] ?? raw;
      default:
        return raw;
    }
  }
